#include <bits/stdc++.h>
#define FOR(i,s,t) for(int i=s;i<=t;i++)
using namespace std;
const int MOD=1e9+7;
int qpow(int base,int exp){
	if(exp==0) return 1;
	int half=qpow(base,exp>>1);
	half=1ll*half*half%MOD;
	if(exp&1) half=1ll*half*base%MOD;
	return half;
}
vector<int> combs;
int p[10][10], f[1<<20], g[1<<20];
int main(){
	int n; cin>>n;
	FOR(i,0,n-1) FOR(j,0,n-1){
		int per; cin>>per;
		p[i][j]=1ll*per*qpow(100,MOD-2)%MOD;
	}
	FOR(i,n,5) p[i][i]=1;
	FOR(i,0,63){
		int count=0;
		FOR(j,0,5) if(i&(1<<j)) count++;
		if(count==3) combs.push_back(i);
	}
	FOR(i,0,(1<<18)-1){
		bool b[6][6]={0};
		int tmp=0,mask=0,prob=1;
		FOR(j,0,5) FOR(k,0,2){
			if(i&(1<<tmp)) b[j][k]=true,prob=1ll*prob*p[j][k]%MOD;
			else prob=1ll*prob*(1-p[j][k]+MOD)%MOD;
			tmp++;
		}
		FOR(j,0,19){
			int p_list[3],p_count=0;
			FOR(k,0,5) if(combs[j]&(1<<k)) p_list[p_count++]=k;
			int p1=p_list[0],p2=p_list[1],p3=p_list[2];
			if((b[p1][0]&&b[p2][1]&&b[p3][2])||(b[p1][0]&&b[p2][2]&&b[p3][1])||
			   (b[p1][1]&&b[p2][0]&&b[p3][2])||(b[p1][1]&&b[p2][2]&&b[p3][0])||
			   (b[p1][2]&&b[p2][0]&&b[p3][1])||(b[p1][2]&&b[p2][1]&&b[p3][0])) mask|=1<<j;
		}
		f[mask]=(f[mask]+prob)%MOD;
	}
	FOR(i,0,(1<<18)-1){
		bool b[6][6]={0};
		int tmp=0,mask=0,prob=1;
		FOR(j,0,5) FOR(k,3,5){
			if(i&(1<<tmp)) b[j][k]=true,prob=1ll*prob*p[j][k]%MOD;
			else prob=1ll*prob*(1-p[j][k]+MOD)%MOD;
			tmp++;
		}
		FOR(j,0,19){
			int p_list[3],p_count=0,s=combs[j]^63;
			FOR(k,0,5) if(s&(1<<k)) p_list[p_count++]=k;
			int p1=p_list[0],p2=p_list[1],p3=p_list[2];
			if((b[p1][3]&&b[p2][4]&&b[p3][5])||(b[p1][3]&&b[p2][5]&&b[p3][4])||
			   (b[p1][4]&&b[p2][3]&&b[p3][5])||(b[p1][4]&&b[p2][5]&&b[p3][3])||
			   (b[p1][5]&&b[p2][3]&&b[p3][4])||(b[p1][5]&&b[p2][4]&&b[p3][3])) mask|=1<<j;
		}
		g[mask]=(g[mask]+prob)%MOD;
	}
	FOR(i,0,19) for(int j=(1<<20)-1;j>=0;j--) if(j&(1<<i)) g[j]=(g[j]+g[j^(1<<i)])%MOD;
	int answer=0;
	FOR(i,0,(1<<20)-1) answer=(answer+1ll*f[i]*g[(1<<20)-1^i])%MOD;
	cout<<(1-answer+MOD)%MOD<<endl;
	return 0;
}
